package completion

import (
	"fmt"
	"strings"
)

// zshScript renders the zsh completion for mlop.
//
// Structure: _arguments -C dispatches on the first word (the
// command), then on the remaining words (the command's arguments).
// Deployment names come from `mlop __complete-names` through the
// _mlop_names helper, which passes --state through when the user
// gave one. `rollout` completes its `status` subcommand first.
func zshScript() string {
	var b strings.Builder
	b.WriteString(`#compdef mlop
# zsh completion for mlop.
# Generated by ` + "`mlop completion zsh`" + `; do not edit by hand.
# Install it with:
#   mlop completion zsh > "${fpath[1]}/_mlop"
# or drop it in any directory on your $fpath and run compinit.

_mlop_names() {
    # Deployment names from the same state file this shell uses.
    local state_file="" i
    for (( i=1; i<=$#words; i++ )); do
        if [[ $words[i] == --state && $((i+1)) -le $#words ]]; then
            state_file=$words[i+1]
        fi
    done
    local -a names
    if [[ -n "$state_file" ]]; then
        names=( ${(f)"$(mlop --state "$state_file" __complete-names 2>/dev/null)"} )
    else
        names=( ${(f)"$(mlop __complete-names 2>/dev/null)"} )
    fi
    _describe -t deployments 'deployment' names
}

_mlop() {
    local state line
    typeset -A opt_args
    local -a _mlop_commands
    _mlop_commands=(
`)
	for _, c := range Commands() {
		fmt.Fprintf(&b, "        %s\n", quoteZsh(c.Name+":"+c.Description))
	}
	b.WriteString(`    )

    _arguments -C \
        '--state[ path to the mlop state file]:state file:_files' \
        '1:command:->command' \
        '*::arguments:->args'

    case $state in
        command)
            _describe -t commands 'mlop command' _mlop_commands
            ;;
        args)
            # The command word: first non-option word after mlop,
            # skipping --state's value. $words[2] is wrong once
            # --state is on the line, so scan for it.
            local cmd="" sub="" i
            for (( i=2; i<=$#words; i++ )); do
                if [[ $words[i] == --state ]]; then (( i++ )); continue; fi
                if [[ $words[i] == -* ]]; then continue; fi
                if [[ -z "$cmd" ]]; then cmd=$words[i]; continue; fi
                sub=$words[i]
                break
            done
            case $cmd in
`)
	for _, c := range Commands() {
		b.WriteString("                " + c.Name + ")\n")
		b.WriteString(zshArgsFor(c))
		b.WriteString("                    ;;\n")
	}
	b.WriteString(`            esac
            ;;
    esac

    case $state in
        names)
            _mlop_names
            ;;
        rollout_args)
            case $sub in
                status)
                    _arguments '1:deployment:->names'
                    ;;
            esac
            ;;
    esac
}

_mlop "$@"
`)
	return b.String()
}

// zshArgsFor renders the _arguments call for one command: its flags,
// then either a deployment name (state ->names), a file, a
// subcommand, or nothing.
func zshArgsFor(c Command) string {
	var b strings.Builder
	write := func(format string, args ...any) {
		fmt.Fprintf(&b, "                    "+format+"\n", args...)
	}
	// _arguments with no specs is a no-op; commands with neither
	// flags nor positionals (crd, version, help) get nothing.
	if len(c.Flags) == 0 && !c.TakesName && !c.TakesFile && len(c.Subcommands) == 0 {
		return ""
	}
	write("_arguments \\")
	specs := []string{}
	for _, f := range c.Flags {
		specs = append(specs, zshFlagSpec(f))
	}
	if len(c.Subcommands) > 0 {
		// rollout: the subcommand word, then its arguments.
		sub := strings.Join(c.Subcommands, " ")
		specs = append(specs, fmt.Sprintf("'1:subcommand:(%s)'", sub))
		if c.Name == "rollout" {
			specs = append(specs, "'*::arguments:->rollout_args'")
		}
	} else if c.TakesName {
		specs = append(specs, "'1:deployment:->names'")
	} else if c.TakesFile {
		specs = append(specs, "'1:file:_files'")
	}
	for i, s := range specs {
		if i == len(specs)-1 {
			write("    %s", s)
		} else {
			write("    %s \\", s)
		}
	}
	return b.String()
}

// zshFlagSpec renders one flag as an _arguments spec. Value flags
// (-f, --tail, ...) take a value: files for -f/-d, a plain value
// for the rest.
func zshFlagSpec(f string) string {
	switch f {
	case "-f":
		return "'-f[ manifest file]:manifest:_files'"
	case "-d":
		return "'-d[ directory of manifests]:directory:_files -/'"
	case "--tail", "--replicas":
		return fmt.Sprintf("'%s[ count]:count:'", f)
	case "--interval", "--timeout":
		return fmt.Sprintf("'%s[ duration]:duration:'", f)
	case "--namespace":
		return fmt.Sprintf("'%s[ operator namespace]:namespace:'", f)
	case "--image":
		return fmt.Sprintf("'%s[ operator image]:image:'", f)
	default:
		// Boolean flags.
		return fmt.Sprintf("'%s[%s]'", f, strings.TrimLeft(f, "-"))
	}
}

// quoteZsh single-quotes a string for the _describe table, escaping
// embedded single quotes the shell way.
func quoteZsh(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}
